previewCss:
.darma-loader-darma-b13-toaster-pop { --accent: var(--loader-color, #64748b); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 100px); height: calc(var(--loader-size, 100px) * .82); position: relative; }
.darma-loader-darma-b13-toaster-pop .darma-loader-darma-b13-toaster-pop__shell { position: absolute; z-index: 2; bottom: 0; left: 0; width: 100%; height: 56%; border-radius: 12% 12% 16% 16%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 26%, var(--accent))); box-shadow: inset 0 3px 6px rgba(255, 255, 255, .28); }
.darma-loader-darma-b13-toaster-pop .darma-loader-darma-b13-toaster-pop__shell::after { content: ''; position: absolute; top: 12%; left: 10%; width: 80%; height: 14%; border-radius: 999px; background: color-mix(in srgb, #000 55%, var(--accent)); }
.darma-loader-darma-b13-toaster-pop::after { content: ''; position: absolute; z-index: 3; bottom: 24%; right: -3%; width: 12%; height: 7%; border-radius: 999px; background: #cbd5e1; }
.darma-loader-darma-b13-toaster-pop span { position: absolute; bottom: 44%; width: 34%; height: 42%; border-radius: 7px 7px 2px 2px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent-2)); animation: darma-loader-darma-b13-toaster-pop-toast calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.3, 1.5, .5, 1) infinite; }
.darma-loader-darma-b13-toaster-pop span:nth-child(1) { left: 11%; }
.darma-loader-darma-b13-toaster-pop span:nth-child(2) { right: 11%; animation-delay: calc(var(--loader-speed, 1s) * .16); }
@keyframes darma-loader-darma-b13-toaster-pop-toast { 0%, 24% { transform: translateY(62%); } 52% { transform: translateY(-32%); } 76%, 100% { transform: translateY(62%); } }

